UPDATE fcc_flow_step_execution
SET status = #{previousStatus},
    ended_at = UTC_TIMESTAMP(3),
    duration_ms = GREATEST(
      0,
      TIMESTAMPDIFF(MICROSECOND, started_at, UTC_TIMESTAMP(3)) DIV 1000
    ),
    output_json = #{output}
WHERE flow_instance_id = #{call}
  AND ended_at IS NULL
